update public.statistics s set agency = m.good, updated_at = now() from (values ('국가데이터처구동향과','국가데이터처 인구동향과'), ('국가데이터처구총조사과','국가데이터처 인구총조사과'), ('국가데이터처구추계팀','국가데이터처 인구추계팀'), ('국가데이터처비스업동향과','국가데이터처 서비스업동향과'), ('국가데이터처어업동향과','국가데이터처 농어업동향과'), ('국가데이터처업동향과','국가데이터처 산업동향과'), ('국가데이터처업통계과','국가데이터처 산업통계과'), ('국가데이터처용통계과','국가데이터처 고용통계과'), ('국가데이터처정통계과','국가데이터처 행정통계과'), ('국가데이터처제통계기획과','국가데이터처 경제통계기획과'), ('국가데이터처회통계기획과','국가데이터처 사회통계기획과')) as m(bad, good) where s.agency = m.bad;